--
-- Name: ash_trim_whitespace(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ash_trim_whitespace(arr text[]) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    start_index INT = 1;
    end_index INT = array_length(arr, 1);
BEGIN
    WHILE start_index <= end_index AND arr[start_index] = '' LOOP
        start_index := start_index + 1;
    END LOOP;

    WHILE end_index >= start_index AND arr[end_index] = '' LOOP
        end_index := end_index - 1;
    END LOOP;

    IF start_index > end_index THEN
        RETURN ARRAY[]::text[];
    ELSE
        RETURN arr[start_index : end_index];
    END IF;
END; $$;


--
-- Name: check_conversation_message_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_conversation_message_content() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_tenant uuid; owner_message uuid;
BEGIN
  IF TG_TABLE_NAME='conversation_messages' THEN
    owner_tenant=NEW.tenant_id; owner_message=NEW.id;
  ELSE
    owner_tenant=COALESCE(NEW.tenant_id,OLD.tenant_id); owner_message=COALESCE(NEW.message_id,OLD.message_id);
  END IF;
  IF EXISTS (SELECT 1 FROM conversation_messages m WHERE m.tenant_id=owner_tenant AND m.id=owner_message
    AND m.origin='native' AND btrim(COALESCE(m.text,''))='' AND NOT EXISTS (
      SELECT 1 FROM message_attachments a WHERE a.tenant_id=m.tenant_id AND a.message_id=m.id)) THEN
    RAISE EXCEPTION 'Native messages require text or an attachment' USING ERRCODE='23514',CONSTRAINT='conversation_messages_text_present';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: check_page_comment_root(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_page_comment_root() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.root_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM page_comments root
    WHERE root.tenant_id = NEW.tenant_id AND root.page_id = NEW.page_id AND root.id = NEW.root_id AND root.root_id IS NULL
  ) THEN
    RAISE EXCEPTION 'Replies must reference a root comment on the same page' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: meta_page_type_boundary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meta_page_type_boundary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE root_key text;
BEGIN
  WITH RECURSIVE ancestors AS (
    SELECT id,parent_id,system_key FROM pages WHERE tenant_id=NEW.tenant_id AND id=NEW.id
    UNION ALL SELECT p.id,p.parent_id,p.system_key FROM pages p JOIN ancestors a ON a.parent_id=p.id
      WHERE p.tenant_id=NEW.tenant_id)
  SELECT system_key INTO root_key FROM ancestors WHERE parent_id IS NULL;
  IF (root_key IS DISTINCT FROM 'ankole_brain' AND NEW.type='knowledge') OR
     (root_key='ankole_brain' AND NEW.type NOT IN ('knowledge','file')) THEN
    RAISE EXCEPTION 'page type is outside its owning domain' USING ERRCODE='23514',CONSTRAINT='pages_domain_type';
  END IF;
  RETURN NEW;
END $$;


