    CONSTRAINT agents_uid_agent_home_safe CHECK ((uid ~ '^[a-z0-9][a-z0-9._@+-]{0,95}$'::text)),
    CONSTRAINT personal_assistant_strict_memory CHECK (((type <> 'personal_assistant'::public.agent_type) OR (group_memory_disclosure_mode = 'strict'::text)))
);


