--

CREATE TABLE public.ai_gateway_usage_records (
    id uuid NOT NULL,
    subject_uid text NOT NULL,
    origin text NOT NULL,
    model text NOT NULL,
    input_tokens bigint,
    output_tokens bigint,
    inserted_at timestamp without time zone NOT NULL,
    tenant_id uuid NOT NULL,
    session_id text,
    signal_id uuid,
    job_id bigint,
    attempt integer,
    cached_input_tokens bigint,
    reasoning_tokens bigint,
    provider_model text,
    model_profile text,
    served_profile text,
    human_uid text,
    cache_creation_input_tokens bigint,
    capability text DEFAULT 'llm'::text NOT NULL,
    unit text,
    quantity bigint,
    provider_cost numeric,
    CONSTRAINT ai_gateway_usage_records_attempt_check CHECK (((attempt IS NULL) OR (attempt >= 0))),
    CONSTRAINT ai_gateway_usage_records_cache_creation_input_tokens_check CHECK (((cache_creation_input_tokens IS NULL) OR (cache_creation_input_tokens >= 0))),
    CONSTRAINT ai_gateway_usage_records_cached_input_tokens_check CHECK (((cached_input_tokens IS NULL) OR (cached_input_tokens >= 0))),
    CONSTRAINT ai_gateway_usage_records_capability_check CHECK ((capability = ANY (ARRAY['llm'::text, 'image_generate'::text, 'decision'::text, 'speech'::text, 'transcription'::text, 'ocr'::text, 'video'::text, 'music'::text]))),
    CONSTRAINT ai_gateway_usage_records_input_tokens_check CHECK ((input_tokens >= 0)),
    CONSTRAINT ai_gateway_usage_records_job_id_check CHECK (((job_id IS NULL) OR (job_id > 0))),
    CONSTRAINT ai_gateway_usage_records_origin_check CHECK ((origin = ANY (ARRAY['agent'::text, 'codex'::text, 'applet'::text, 'brain'::text, 'oidc_human'::text, 'compaction'::text, 'pod_files'::text]))),
    CONSTRAINT ai_gateway_usage_records_output_tokens_check CHECK ((output_tokens >= 0)),
    CONSTRAINT ai_gateway_usage_records_provider_cost_check CHECK (((provider_cost IS NULL) OR (provider_cost >= (0)::numeric))),
    CONSTRAINT ai_gateway_usage_records_quantity_check CHECK ((((unit IS NULL) AND (quantity IS NULL)) OR ((unit = ANY (ARRAY['image'::text, 'character'::text, 'second'::text, 'page'::text])) AND (quantity >= 0)))),
    CONSTRAINT ai_gateway_usage_records_reasoning_tokens_check CHECK (((reasoning_tokens IS NULL) OR (reasoning_tokens >= 0)))
);


