--

CREATE TABLE public.authn_challenges (
    id uuid NOT NULL,
    strategy text NOT NULL,
    purpose text NOT NULL,
    factor_stage text DEFAULT 'primary'::text NOT NULL,
    browser_session_id uuid,
    tenant_id uuid,
    principal_uid text,
    target text,
    secret_digest bytea,
    ceremony_context jsonb DEFAULT '{}'::jsonb NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    challenge_started_at timestamp without time zone NOT NULL,
    expires_at timestamp without time zone,
    verified_at timestamp without time zone,
    inserted_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    CONSTRAINT authn_challenges_anchor CHECK (((browser_session_id IS NOT NULL) OR (purpose = 'setup'::text))),
    CONSTRAINT authn_challenges_attempts CHECK (((attempt_count >= 0) AND (max_attempts >= 1) AND (attempt_count <= max_attempts))),
    CONSTRAINT authn_challenges_consumed CHECK ((((verified_at IS NULL) AND (attempt_count < max_attempts)) OR ((secret_digest IS NULL) AND (expires_at IS NULL)))),
    CONSTRAINT authn_challenges_factor_stage CHECK ((factor_stage = ANY (ARRAY['primary'::text, 'secondary'::text, 'step_up'::text]))),
    CONSTRAINT authn_challenges_target CHECK (((target IS NOT NULL) OR (principal_uid IS NOT NULL) OR (strategy = 'passkey'::text)))
);


--
-- Name: automation_job_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_job_runs (
    id bigint NOT NULL,
    automation_job_id bigint NOT NULL,
    event jsonb NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    attempt_id uuid,
    started_at timestamp without time zone,
    finished_at timestamp without time zone,
    exit_code integer,
    error text,
    stdout text DEFAULT ''::text NOT NULL,
    stderr text DEFAULT ''::text NOT NULL,
    stdout_truncated boolean DEFAULT false NOT NULL,
    stderr_truncated boolean DEFAULT false NOT NULL,
    inserted_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    tenant_id uuid NOT NULL,
    signal_id text,
    causation_id text,
    correlation_id text,
    binding_id uuid,
    concurrency_key text DEFAULT 'default'::text NOT NULL,
    coalesce_key text,
    slice_count integer DEFAULT 0 NOT NULL,
    attempts_in_slice integer DEFAULT 0 NOT NULL,
    attempt_idempotent boolean DEFAULT false NOT NULL,
    attempt_deadline_at timestamp with time zone,
    progress jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_published_revision bigint,
    result jsonb,
    CONSTRAINT automation_job_runs_attempts_in_slice_check CHECK ((attempts_in_slice >= 0)),
