    CONSTRAINT brain_dataset_bindings_source_shape CHECK ((((source_kind = 'base'::text) AND (base_page_id IS NOT NULL) AND (base_table_id IS NOT NULL) AND (connection_slug IS NULL) AND (source_table IS NULL)) OR ((source_kind = 'connector'::text) AND (connection_slug IS NOT NULL) AND (source_table IS NOT NULL) AND (base_page_id IS NULL) AND (base_table_id IS NULL))))
);


