--
-- Name: pages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pages (
    tenant_id uuid NOT NULL,
    id uuid NOT NULL,
    parent_id uuid,
    name text NOT NULL,
    type text CONSTRAINT pages_kind_not_null NOT NULL,
    private_owner_uid text,
    conversation_id uuid,
    inherit_permissions boolean DEFAULT true NOT NULL,
    has_local_acl boolean DEFAULT false NOT NULL,
    is_acl_anchor boolean GENERATED ALWAYS AS (((parent_id IS NULL) OR (NOT inherit_permissions) OR has_local_acl OR (deleted_at IS NOT NULL))) STORED,
    acl_anchor_id uuid NOT NULL,
    parent_anchor_id uuid,
    object_id uuid,
    mode integer DEFAULT 420 NOT NULL,
    content_type text,
    source text,
    message_id uuid,
    source_conversation_id uuid,
    created_by text,
    deleted_at timestamp with time zone,
    purge_started_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    system_key text,
    last_vfs_req_id uuid,
    last_vfs_etag text,
    owner_uid text,
    title text DEFAULT ''::text CONSTRAINT pages_title_not_null1 NOT NULL,
    icon text,
    "position" text COLLATE pg_catalog."C",
    revision bigint DEFAULT 0 CONSTRAINT pages_revision_not_null1 NOT NULL,
    saved_from_message_id uuid,
    children_view jsonb DEFAULT '{}'::jsonb CONSTRAINT pages_children_view_not_null1 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb CONSTRAINT pages_metadata_not_null1 NOT NULL,
    upstream_state jsonb DEFAULT '{}'::jsonb CONSTRAINT pages_upstream_state_not_null1 NOT NULL,
    vfs_md_size bigint,
    vfs_md_blake3 text,
    vfs_content_empty boolean,
    is_root boolean GENERATED ALWAYS AS ((parent_id IS NULL)) STORED,
    CONSTRAINT pages_acl_anchor_shape CHECK (((is_acl_anchor AND (acl_anchor_id = id) AND (((parent_id IS NULL) AND (parent_anchor_id IS NULL)) OR ((parent_id IS NOT NULL) AND (parent_anchor_id IS NOT NULL) AND (parent_anchor_id <> id)))) OR ((NOT is_acl_anchor) AND (parent_id IS NOT NULL) AND (acl_anchor_id <> id) AND (parent_anchor_id IS NULL)))),
    CONSTRAINT pages_children_view_object CHECK ((jsonb_typeof(children_view) = 'object'::text)),
    CONSTRAINT pages_metadata_object CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT pages_mode CHECK (((mode >= 0) AND (mode <= 511))),
    CONSTRAINT pages_name_shape CHECK ((((octet_length(name) >= 1) AND (octet_length(name) <= 255)) AND (name <> ALL (ARRAY['.'::text, '..'::text])) AND (POSITION(('/'::text) IN (name)) = 0))),
    CONSTRAINT pages_object_shape CHECK (((object_id IS NULL) OR (type = 'file'::text))),
    CONSTRAINT pages_purge_state CHECK (((purge_started_at IS NULL) OR (deleted_at IS NOT NULL))),
    CONSTRAINT pages_revision_check CHECK ((revision >= 0)),
    CONSTRAINT pages_root_shape CHECK ((((parent_id IS NULL) AND (type = 'doc'::text) AND (system_key IS NULL) AND (num_nonnulls(private_owner_uid, conversation_id) <= 1)) OR ((parent_id IS NULL) AND (type = 'knowledge'::text) AND (system_key = 'ankole_brain'::text) AND (private_owner_uid IS NULL) AND (conversation_id IS NULL)) OR ((parent_id IS NOT NULL) AND (private_owner_uid IS NULL) AND (conversation_id IS NULL)))),
    CONSTRAINT pages_type CHECK ((type = ANY (ARRAY['doc'::text, 'knowledge'::text, 'base'::text, 'applet'::text, 'file'::text]))),
    CONSTRAINT pages_upstream_state_object CHECK ((jsonb_typeof(upstream_state) = 'object'::text))
);


