);


--
-- Name: brain_page_nodes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.brain_page_nodes AS
 SELECT t.id AS tenant_id,
    p.id,
    p.path AS slug,
    COALESCE((p.metadata ->> 'entity_type'::text), p.type) AS type,
    (p.metadata ->> 'subtype'::text) AS subtype,
    p.title,
        CASE
            WHEN (p.type = 'file'::text) THEN COALESCE(psd.body_text, ''::text)
            ELSE COALESCE(c.plain_text, ''::text)
        END AS body,
    COALESCE(c.content, '<page />'::text) AS xml,
    p.metadata AS meta,
    p.upstream_state,
    p.revision,
    p.parent_id,
    p.acl_anchor_id,
    p.is_acl_anchor,
    p.type AS kind,
        CASE
            WHEN (((p.metadata ->> 'effective_date'::text) ~ '^\d{4}-\d{2}-\d{2}$'::text) AND pg_input_is_valid((p.metadata ->> 'effective_date'::text), 'date'::text)) THEN ((p.metadata ->> 'effective_date'::text))::date
            ELSE NULL::date
        END AS effective_date,
        CASE
            WHEN (fc.page_id IS NOT NULL) THEN (((COALESCE(encode(fo.sha256, 'hex'::text), (fc.object_id)::text) || ':v'::text) || (fc.extractor_version)::text) || COALESCE((':ocr'::text || (NULLIF(jsonb_array_length((fc.metadata -> 'ocr_pages'::text)), 0))::text), ''::text))
            ELSE (p.revision)::text
        END AS content_hash,
    ((p.upstream_state ->> 'source_id'::text))::uuid AS managed_by_source_id,
    p.deleted_at,
    p.created_at,
    p.updated_at,
        CASE
            WHEN (fc.page_id IS NOT NULL) THEN jsonb_build_object('format', fc.format, 'extract_status', fc.extract_status, 'metadata', fc.metadata)
            ELSE NULL::jsonb
        END AS file
   FROM (((((public.tenants t
     CROSS JOIN LATERAL ( WITH RECURSIVE paths AS (
                 SELECT pages.id,
                    pages.system_key,
                    ''::text AS path
                   FROM public.pages
                  WHERE ((pages.tenant_id = t.id) AND (pages.parent_id IS NULL))
                UNION ALL
                 SELECT n.id,
                    n.system_key,
                        CASE
                            WHEN ((parent.path = ''::text) OR (parent.system_key = 'ankole_brain'::text)) THEN n.name
                            ELSE ((parent.path || '/'::text) || n.name)
                        END AS "case"
                   FROM (public.pages n
                     JOIN paths parent ON (((n.tenant_id = t.id) AND (n.parent_id = parent.id))))
                )
         SELECT page.id,
            page.parent_id,
            page.type,
            page.title,
            page.metadata,
            page.upstream_state,
            page.revision,
            page.acl_anchor_id,
            page.is_acl_anchor,
            page.deleted_at,
            page.created_at,
            page.updated_at,
            paths.path
           FROM (paths
             JOIN public.pages page ON (((page.tenant_id = t.id) AND (page.id = paths.id))))
          WHERE ((page.parent_id IS NOT NULL) AND (page.type = ANY (ARRAY['knowledge'::text, 'doc'::text, 'base'::text, 'applet'::text, 'file'::text])))
         OFFSET 0) p)
     LEFT JOIN public.page_contents c ON (((c.tenant_id = t.id) AND (c.page_id = p.id))))
     LEFT JOIN public.page_search_documents psd ON (((p.type = 'file'::text) AND (psd.tenant_id = t.id) AND (psd.page_id = p.id))))
     LEFT JOIN public.pod_file_caches fc ON (((p.type = 'file'::text) AND (fc.tenant_id = t.id) AND (fc.page_id = p.id))))
     LEFT JOIN public.file_objects fo ON (((fo.tenant_id = fc.tenant_id) AND (fo.id = fc.object_id))));


