    CONSTRAINT conversation_messages_kind_check CHECK ((kind = ANY (ARRAY['message'::text, 'notice'::text]))),
    CONSTRAINT conversation_messages_origin_check CHECK ((origin = ANY (ARRAY['native'::text, 'external'::text]))),
    CONSTRAINT conversation_messages_provenance_check CHECK (((btrim(delivery_key) <> ''::text) AND (((origin = 'native'::text) AND (author_display_name IS NOT NULL) AND (btrim(author_display_name) <> ''::text) AND (((author_type = 'human'::text) AND (signal_id IS NULL) AND (session_id IS NULL)) OR ((author_type = 'agent'::text) AND (session_id IS NOT NULL) AND (btrim(session_id) <> ''::text)))) OR (origin = 'external'::text)))),
    CONSTRAINT conversation_messages_sequence_positive CHECK ((seq > 0))
);


