-- Name: conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversations (
    tenant_id uuid NOT NULL,
    id uuid NOT NULL,
    kind text DEFAULT 'native'::text NOT NULL,
    title text NOT NULL,
    created_by text,
    last_activity_at timestamp without time zone NOT NULL,
    inserted_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    sequence_high_water bigint DEFAULT 0 NOT NULL,
    provider_conversation_id text,
    external_kind text,
    reply_mode text,
    visibility text,
    principal_group_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    raw_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    first_seen_at timestamp(6) without time zone,
    last_seen_at timestamp(6) without time zone,
    ambient_standing_orders text,
    ambient_standing_orders_set_by text,
    ambient_standing_orders_updated_at timestamp(6) without time zone,
    page_id uuid,
    room_mode text,
    native_access_scope text,
    title_customized boolean DEFAULT false NOT NULL,
    preferred_models jsonb DEFAULT '{}'::jsonb NOT NULL,
    dm_human_uid text,
    dm_colleague_uid text,
    origin_conversation_id uuid,
    peer_sender_uid text,
    peer_target_uid text,
    last_notifiable_seq bigint DEFAULT 0 NOT NULL,
    CONSTRAINT conversations_dm_identity_check CHECK ((((dm_human_uid IS NULL) AND (dm_colleague_uid IS NULL)) OR ((dm_human_uid IS NOT NULL) AND (dm_colleague_uid IS NOT NULL) AND (kind = 'native'::text) AND (room_mode = 'dm'::text) AND (native_access_scope = 'participants'::text)))),
    CONSTRAINT conversations_kind_check CHECK ((kind = ANY (ARRAY['native'::text, 'external'::text]))),
    CONSTRAINT conversations_native_room_check CHECK ((((kind = 'native'::text) AND (room_mode IS NOT NULL) AND (room_mode = ANY (ARRAY['dm'::text, 'group'::text])) AND (native_access_scope IS NOT NULL) AND (native_access_scope = ANY (ARRAY['participants'::text, 'anchor_page'::text, 'agent_peer'::text])) AND ((native_access_scope <> 'anchor_page'::text) OR (page_id IS NOT NULL)) AND (jsonb_typeof(preferred_models) = 'object'::text)) OR ((kind = 'external'::text) AND (room_mode IS NULL) AND (native_access_scope IS NULL)))),
    CONSTRAINT conversations_notifiable_sequence_check CHECK (((last_notifiable_seq >= 0) AND (last_notifiable_seq <= sequence_high_water))),
    CONSTRAINT conversations_origin_check CHECK ((((kind = 'native'::text) AND (created_by IS NOT NULL) AND (provider_conversation_id IS NULL)) OR ((kind = 'external'::text) AND (provider_conversation_id IS NOT NULL) AND (btrim(provider_conversation_id) <> ''::text) AND (external_kind IS NOT NULL) AND (reply_mode IS NOT NULL)))),
    CONSTRAINT conversations_page_origin_check CHECK (((page_id IS NULL) OR (kind = 'native'::text))),
    CONSTRAINT conversations_peer_identity_check CHECK ((((native_access_scope = 'agent_peer'::text) AND (peer_sender_uid IS NOT NULL) AND (peer_target_uid IS NOT NULL) AND (peer_sender_uid <> peer_target_uid)) OR ((native_access_scope IS DISTINCT FROM 'agent_peer'::text) AND (peer_sender_uid IS NULL) AND (peer_target_uid IS NULL) AND (origin_conversation_id IS NULL)))),
    CONSTRAINT conversations_sequence_high_water_check CHECK ((sequence_high_water >= 0)),
    CONSTRAINT conversations_title_present CHECK ((btrim(title) <> ''::text))
);


