    CONSTRAINT deliveries_attempts_non_negative CHECK (((attempt_count >= 0) AND (max_attempts > 0))),
    CONSTRAINT deliveries_delivery_class_check CHECK ((delivery_class = ANY (ARRAY['generic'::text, 'durable_ai_reply'::text]))),
    CONSTRAINT deliveries_duplicate_notice_requires_flag CHECK (((possible_duplicate_notice IS NULL) OR (possible_duplicate AND (btrim(possible_duplicate_notice) <> ''::text)))),
    CONSTRAINT deliveries_last_error_object CHECK ((jsonb_typeof(last_error) = 'object'::text)),
    CONSTRAINT deliveries_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text)),
