    CONSTRAINT deliveries_recovery_state_object CHECK ((jsonb_typeof(recovery_state) = 'object'::text)),
    CONSTRAINT deliveries_recovery_status_delivery CHECK (((recovery_status IS NULL) OR (status = ANY (ARRAY['failed'::public.delivery_status, 'unknown'::public.delivery_status])))),
    CONSTRAINT deliveries_recovery_status_valid CHECK ((recovery_status = ANY (ARRAY['blocked'::text, 'permanent'::text, 'exhausted'::text])))
);


--
-- Name: TABLE deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.deliveries IS 'Durable provider-visible side-effect intents committed by actor events.';


--
-- Name: COLUMN deliveries.agent_uid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.agent_uid IS 'Agent principal that owns the outbound side effect.';


