-- Name: COLUMN deliveries.binding_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.binding_name IS 'Output binding that should dispatch the side effect.';


--
-- Name: COLUMN deliveries.outbound_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.outbound_key IS 'Agent-provided idempotency key for the side effect.';


--
-- Name: COLUMN deliveries.operation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.operation IS 'Provider-visible operation requested by the actor.';


--
-- Name: COLUMN deliveries.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.status IS 'Dispatch state for retry and recovery.';


--
-- Name: COLUMN deliveries.provider_thread_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.provider_thread_id IS 'Provider thread targeted by the side effect.';


--
-- Name: COLUMN deliveries.reply_to_provider_message_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.reply_to_provider_message_id IS 'Provider entry that the side effect replies from.';


--
-- Name: COLUMN deliveries.target_provider_message_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deliveries.target_provider_message_id IS 'Provider entry targeted by edit, delete, or reaction operations.';


--
