    CONSTRAINT oidc_clients_name_present CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT oidc_clients_openid_scope CHECK ((scopes @> ARRAY['openid'::text])),
    CONSTRAINT oidc_clients_secret_shape CHECK ((((client_type = 'public'::text) AND (secret_ciphertext IS NULL)) OR ((client_type = 'confidential'::text) AND (secret_ciphertext IS NOT NULL)))),
    CONSTRAINT oidc_clients_type CHECK ((client_type = ANY (ARRAY['public'::text, 'confidential'::text])))
