--
-- Name: permission_grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.permission_grants (
    id uuid NOT NULL,
    principal_uid text,
    group_id uuid,
    resource_pattern text NOT NULL,
    action text NOT NULL,
    condition text DEFAULT 'true'::text NOT NULL,
    description text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    inserted_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    tenant_id uuid NOT NULL,
    source_node_id uuid,
    source_action text,
    target_node_id uuid,
    target_scope text,
    CONSTRAINT permission_grants_action_no_colon CHECK ((POSITION((':'::text) IN (action)) = 0)),
    CONSTRAINT permission_grants_action_present CHECK ((length(btrim(action)) > 0)),
    CONSTRAINT permission_grants_condition_present CHECK ((length(btrim(condition)) > 0)),
    CONSTRAINT permission_grants_drive_action_shape CHECK ((((action <> ALL (ARRAY['node_view'::text, 'node_contribute'::text, 'node_edit'::text, 'node_manage'::text, 'node_comment'::text])) AND (target_node_id IS NULL) AND (target_scope IS NULL) AND (resource_pattern <> '**'::text) AND (resource_pattern !~~ 'drive:%'::text)) OR ((action = ANY (ARRAY['node_view'::text, 'node_contribute'::text, 'node_edit'::text, 'node_manage'::text, 'node_comment'::text])) AND (((target_node_id IS NULL) AND (target_scope IS NULL) AND ((resource_pattern = 'drive:space:**'::text) OR (resource_pattern ~ '^drive:private:[^*?\[\]{}]+:\*\*$'::text))) OR ((target_node_id IS NOT NULL) AND (target_scope = ANY (ARRAY['container'::text, 'self'::text])) AND (resource_pattern = ((('drive:**:'::text || (target_node_id)::text) || ':'::text) ||
CASE target_scope
    WHEN 'container'::text THEN '**'::text
    ELSE 'node'::text
END)) AND ((source_node_id IS NULL) OR (source_node_id <> target_node_id))))))),
    CONSTRAINT permission_grants_metadata_object CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT permission_grants_owner_shape CHECK (((num_nonnulls(principal_uid, group_id, source_node_id) = 1) AND (((source_node_id IS NULL) AND (source_action IS NULL)) OR ((source_node_id IS NOT NULL) AND (source_action = ANY (ARRAY['node_view'::text, 'node_contribute'::text, 'node_edit'::text, 'node_manage'::text, 'node_comment'::text])) AND (target_node_id IS NOT NULL))))),
    CONSTRAINT permission_grants_resource_pattern_present CHECK ((length(btrim(resource_pattern)) > 0))
);


--
-- Name: TABLE permission_grants; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.permission_grants IS 'Principal or group grants over resource patterns.';


--
-- Name: COLUMN permission_grants.principal_uid; Type: COMMENT; Schema: public; Owner: -
