CREATE TABLE public.session_ambient_judgments (
    signal_id uuid NOT NULL,
    agent_uid text NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    asked_by_state text,
    judged_until timestamp without time zone,
    inserted_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    action text NOT NULL,
    authority text NOT NULL,
    handoff_job_id bigint,
    tenant_id uuid NOT NULL,
    conversation_id uuid,
    asked_by_message_id uuid,
    CONSTRAINT session_ambient_judgments_action_contract_check CHECK (((action = ANY (ARRAY['NOOP'::text, 'FOREGROUND_REPLY'::text, 'NEW_WORK'::text, 'HANDOFF'::text])) AND (authority = ANY (ARRAY['NONE'::text, 'EXPLICIT_REQUEST'::text, 'STANDING_ORDER'::text])) AND ((action = 'NEW_WORK'::text) OR (authority = 'NONE'::text)) AND ((action = 'HANDOFF'::text) = (handoff_job_id IS NOT NULL)) AND ((handoff_job_id IS NULL) OR (handoff_job_id > 0)))),
    CONSTRAINT session_ambient_judgments_asked_by_shape_check CHECK (
CASE asked_by_state
    WHEN 'accepted'::text THEN (asked_by_message_id IS NOT NULL)
    WHEN 'degraded'::text THEN (asked_by_message_id IS NULL)
    ELSE ((asked_by_state IS NULL) AND (asked_by_message_id IS NULL))
END),
    CONSTRAINT session_ambient_judgments_asked_by_state_check CHECK (((asked_by_state IS NULL) OR (asked_by_state = ANY (ARRAY['accepted'::text, 'degraded'::text]))))
);


