    CONSTRAINT signal_webhook_endpoints_lifecycle_check CHECK ((((status = 'fired'::text) AND (fired_at IS NOT NULL) AND (cancelled_at IS NULL)) OR ((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (fired_at IS NULL)) OR ((status = ANY (ARRAY['armed'::text, 'active'::text, 'paused'::text, 'expired'::text])) AND (fired_at IS NULL) AND (cancelled_at IS NULL)))),
