    CONSTRAINT signal_webhook_endpoints_status_check CHECK ((status = ANY (ARRAY['armed'::text, 'active'::text, 'paused'::text, 'fired'::text, 'cancelled'::text, 'expired'::text]))),
    CONSTRAINT signal_webhook_endpoints_token_digest_length CHECK ((length(token_digest) = 43)),
    CONSTRAINT signal_webhook_endpoints_work_authorization_check CHECK ((((authorization_kind = 'human'::text) AND (human_uid IS NOT NULL) AND (human_access_version IS NOT NULL)) OR ((authorization_kind = 'service'::text) AND (human_uid IS NULL) AND (human_access_version IS NULL)) OR (authorization_kind = 'review_required'::text)))
);


