    agent_uid text NOT NULL,
    owner_session_id text NOT NULL,
    reply_route jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_signal_id uuid,
    source_tool_call_id text NOT NULL,
    title text NOT NULL,
    script text NOT NULL,
    args jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'running'::text NOT NULL,
    concurrency integer NOT NULL,
    max_agent_calls integer NOT NULL,
    memo_bytes integer DEFAULT 0 NOT NULL,
    model_profile text,
    result_text text,
    error jsonb DEFAULT '{}'::jsonb NOT NULL,
    completed_at timestamp without time zone,
    cleanup_completed_at timestamp without time zone,
    inserted_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    authorization_kind text DEFAULT 'review_required'::text NOT NULL,
    human_uid text,
    human_access_version bigint,
    tenant_id uuid NOT NULL,
    CONSTRAINT workflow_runs_args_valid CHECK ((jsonb_typeof(args) = 'object'::text)),
    CONSTRAINT workflow_runs_cleanup_lifecycle_check CHECK (((cleanup_completed_at IS NULL) OR (status = ANY (ARRAY['completed'::text, 'failed'::text, 'cancelled'::text])))),
    CONSTRAINT workflow_runs_concurrency_range CHECK (((concurrency >= 1) AND (concurrency <= 32))),
    CONSTRAINT workflow_runs_error_object CHECK ((jsonb_typeof(error) = 'object'::text)),
    CONSTRAINT workflow_runs_id_range CHECK (((id >= 1000) AND (id <= '9007199254740991'::bigint))),
    CONSTRAINT workflow_runs_lifecycle_check CHECK ((((status = 'running'::text) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['completed'::text, 'failed'::text, 'cancelled'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT workflow_runs_max_agent_calls_range CHECK (((max_agent_calls >= 1) AND (max_agent_calls <= 1024))),
    CONSTRAINT workflow_runs_memo_bytes_range CHECK (((memo_bytes >= 0) AND (memo_bytes <= 6291456))),
    CONSTRAINT workflow_runs_model_profile_valid CHECK (((model_profile IS NULL) OR (model_profile ~ '^[a-z][a-z0-9_-]{0,63}$'::text))),
    CONSTRAINT workflow_runs_owner_session_present CHECK ((length(btrim(owner_session_id)) > 0)),
    CONSTRAINT workflow_runs_reply_route_object CHECK ((jsonb_typeof(reply_route) = 'object'::text)),
    CONSTRAINT workflow_runs_result_bounded CHECK (((result_text IS NULL) OR (octet_length(result_text) <= 1048576))),
    CONSTRAINT workflow_runs_script_valid CHECK (((length(btrim(script)) > 0) AND (octet_length(script) <= 262144))),
    CONSTRAINT workflow_runs_source_tool_call_present CHECK ((length(btrim(source_tool_call_id)) > 0)),
    CONSTRAINT workflow_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT workflow_runs_title_valid CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200))),
    CONSTRAINT workflow_runs_work_authorization_check CHECK ((((authorization_kind = 'human'::text) AND (human_uid IS NOT NULL) AND (human_access_version IS NOT NULL) AND (human_access_version > 0)) OR ((authorization_kind = ANY (ARRAY['service'::text, 'review_required'::text])) AND (human_uid IS NULL) AND (human_access_version IS NULL))))
);


